val cache = mutableMapOf<String, Any>()

@Suppress("UNCHECKED_CAST")
fun <T : Any> remember(key: String, calc: () -> T): T =
    cache.getOrPut(key) { calc() } as T

class Box(var n: Int)

fun counter(): Int {
    val a = Box(0)
    val b = remember("b") { Box(0) }
    a.n++
    b.n++
    return a.n * 10 + b.n
}

fun main() {
    println((1..3).map { counter() }.joinToString(" "))
}

